export function make(): { id: number; name: string } {
  return { id: 1, name: 'An' };
}

// infer R captures the type after the arrow (ReturnType<F>).
export type Return<F> = F extends (...args: never[]) => infer R ? R : never;

import type { Return, make } from '../src/return.ts';
const r: Return<typeof make> = { id: 1, name: 'An' }; // { id; name }
const id: number = r.id;
export { id };

import type { Return, make } from '../src/return.ts';
const bad: Return<typeof make> = { id: 'oops', name: 'An' }; // expect TS2322
export { bad };

